public class Main {
    public static void main(String[] args) {
        int billAmount = 1500;
        int discount = 0;
        if (billAmount > 1000) {
            discount = 150;
        }
        int finalAmount = billAmount - discount;
        System.out.println("Payable: Rs " + finalAmount);
    }
}

