public class Main {
    public static void main(String[] args) {
        int outer = 10;
        {
            int inner = 20;
            System.out.println("Outer: " + outer + ", Inner: " + inner);
        }
        System.out.println("Outer still active: " + outer);
    }
}

public class Main {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 1; i <= 5; i++) {
            sum = sum + i;
        }
        System.out.println("Sum of 1 to 5: " + sum);
    }
}

